import MainLayout from "@/layouts/MainLayout";
import Navbar from "@/components/Navbar";

export default function AssignmentsPage() {
  return (
    <MainLayout>
      <Navbar />

      <div className="bg-white rounded-3xl mt-5 h-[85vh] flex flex-col items-center justify-center">
        <img
          src="https://cdn-icons-png.flaticon.com/512/7486/7486740.png"
          className="w-72"
          alt="empty"
        />

        <h1 className="text-4xl font-bold mt-8">No assignments yet</h1>

        <p className="text-gray-500 mt-4">
          Create your first assignment to start collecting and grading student
          submissions.
        </p>

        <button className="mt-8 bg-black text-white px-8 py-4 rounded-full hover:scale-105 transition">
          + Create Your First Assignment
        </button>
      </div>
    </MainLayout>
  );
}
